70:     public static string? GetArg(string[] args, string name)
71:     {
72:         int index = Array.FindIndex(args, a => string.Equals(a, name, StringComparison.OrdinalIgnoreCase));
73:         return index >= 0 && index + 1 < args.Length ? args[index + 1] : null;
