76:     public static void SaveSnapshot(FrameworkElement element, Brush? background, string path)
77:     {
78:         var size = new Size(element.ActualWidth, element.ActualHeight);
79:         var visual = new DrawingVisual();
80:         using (DrawingContext dc = visual.RenderOpen())
81:         {
82:             dc.DrawRectangle(background ?? Brushes.White, null, new Rect(size));
83:             // An absolute viewbox keeps margins and avoids stretching to the drawn content bounds.
84:             var brush = new VisualBrush(element) { Viewbox = new Rect(size), ViewboxUnits = BrushMappingMode.Absolute };
85:             dc.DrawRectangle(brush, null, new Rect(size));
86:         }
87: 
